local _, WFJ = ...
WFJ.Data.add("book", {
  ["2e04015502d3a856"] = { "Per mano di Baros Alexston, Ufficio dell'Architetto Cittadino, ⟦Stormwind=Roccavento⟧. Vostra Maestà, sono molte le ragioni per cui ho ritenuto di dover redigere e presentare un rapporto sulle recenti vicende della \"⟦Defias Brotherhood=Fratellanza dei Defias⟧\" e sulle sue attività in tutto il regno. Per inquadrare la questione, comincerò con un po' di storia. Come Vostra Maestà forse sa, il mio servizio alla città di ⟦Stormwind=Roccavento⟧ iniziò come membro della Gilda dei Tagliapietre. Con anni di lavoro, completammo la ricostruzione di", "." },
  ["2e37509b7c8b8583"] = { "Rapporto sulla situazione dei troll ⟦Frostmane=Mantogelido⟧ nell'area generale della ⟦Coldridge Valley=Valle Crestafredda⟧\n\nRedatto da ⟦Grelin Whitebeard=Grelin Barbabianca⟧, inviato speciale del Senato\n\nDal tempo che ho trascorso a osservare i movimenti dei troll ⟦Frostmane=Mantogelido⟧ nell'area della ⟦Coldridge Valley=Valle Crestafredda⟧, ho stabilito che non rappresentano una grave minaccia per gli insediamenti nanici della zona. Inoltre, è una minaccia che si può eliminare con un modesto supporto aggiuntivo da parte dell'esercito. Con l'aiuto dei montanari già di stanza nella", "." },
  ["2e3806a776b20006"] = { "Thrall condusse gli orchi nel continente di Kalimdor, dove fondarono una nuova patria con l'aiuto dei loro fratelli tauren. Chiamata la loro nuova terra Durotar, in onore del padre assassinato di Thrall, gli orchi vi si stabilirono per ricostruire la loro società, un tempo gloriosa.", "." },
  ["2e4fae4d2ad83683"] = { "Deciso a punire gli orchi ribelli per il loro costoso tradimento, Doomhammer mandò le sue forze a uccidere Gul'dan e a ricondurre i rinnegati all'ovile. Per la sua sconsideratezza, Gul'dan fu fatto a pezzi dai demoni impazziti che egli stesso aveva liberato. Con il loro capo morto, i clan rinnegati caddero in fretta davanti alle legioni furiose di Doomhammer.", "." },
  ["2ec735b2c897e40f"] = { "1. Prendi uno o otto uomo\n2. Picchia uomo forte\n3. Picchia uomo ancora\n4. Metti uomo in fuoco\n5. Mangia uomo", "." },
  ["2edfb23496e6ee12"] = { "Il benevolo Pantheon, cercando di proteggere i suoi mondi ordinati, vigilava sempre contro la minaccia di un attacco da parte delle malvagie entità extradimensionali della ⟦Twisting Nether=Distorsione Fatua⟧. Il Nether, una dimensione eterea di magie caotiche che collegava tra loro gli innumerevoli mondi dell'universo, ospitava un numero infinito di esseri demoniaci e malefici, che cercavano solo di distruggere la vita e di divorare le energie dell'universo vivente.", "." },
  ["2ef01073fe48189f"] = { "Non tutti i mezzorsi sono stati corrotti. Alcuni vivono ancora e cercano di proteggere la foresta. Durante la loro corruzione, alcuni mezzorsi fuggirono, molti furono uccisi e altri furono cacciati dalle loro tribù.\n\nHo trovato un venerabile mezzorso della tribù Foulweald che vive sopra il Lago Mystral: si chiama Krolg.\n\nLo osservo da giorni, e credo che se lo avvicinassi sotto le sembianze di un mezzorso potrei aiutarlo e scoprire un modo per ristabilire un legame tra i nostri popoli.", "." },
  ["2ef47e306d7cc819"] = { "I banchetti\n\nL'usanza di banchettare in questo periodo dell'anno ha origine nella leggenda stessa. Si dice che, quando percorreva Azeroth portando l'inverno al suo passaggio, ⟦Greatfather Winter=Babbo Inverno⟧ offrisse abbondanza a chi accoglieva la sua presenza. Così l'usanza di banchettare durante il Grande Inverno riuniva le comunità, che condividevano tutto ciò che avevano. Di solito un solo giorno di allegria e banchetti accoglieva il cambiamento, in attesa del rinnovamento della terra.", "." },
})
